import type { ActorType, AuditDiff, EngineSettings, Role } from '@ondes/shared';
import { sql } from 'drizzle-orm';
import {
  check,
  foreignKey,
  index,
  jsonb,
  pgTable,
  real,
  text,
  timestamp,
  unique,
  uniqueIndex,
  uuid,
} from 'drizzle-orm/pg-core';

// Tenancy backbone (#5). Contracts: packages/shared/src/contracts/tenancy.ts.
// Every station-scoped table in other domains carries `station_id` referencing `station.id`.

/** Primary key: UUIDv7 (time-ordered, generated by Postgres 18). */
const id = () => uuid('id').primaryKey().default(sql`uuidv7()`);
const createdAt = () => timestamp('created_at', { withTimezone: true }).notNull().defaultNow();
const updatedAt = () =>
  timestamp('updated_at', { withTimezone: true })
    .notNull()
    .defaultNow()
    .$onUpdate(() => new Date());

export const organization = pgTable('organization', {
  id: id(),
  slug: text('slug').notNull().unique(),
  name: text('name').notNull(),
  createdAt: createdAt(),
  updatedAt: updatedAt(),
});

export const station = pgTable(
  'station',
  {
    id: id(),
    orgId: uuid('org_id')
      .notNull()
      .references(() => organization.id, { onDelete: 'restrict' }),
    /** Globally unique: used in public URLs and Icecast mount names. */
    slug: text('slug').notNull().unique(),
    name: text('name').notNull(),
    /** IANA name, validated by the contract (`ianaTimezoneSchema`). */
    timezone: text('timezone').notNull(),
    loudnessTargetLufs: real('loudness_target_lufs').notNull().default(-16),
    truePeakLimitDbtp: real('true_peak_limit_dbtp').notNull().default(-1),
    engineSettings: jsonb('engine_settings').$type<EngineSettings>().notNull().default({}),
    createdAt: createdAt(),
    updatedAt: updatedAt(),
  },
  (t) => [
    index('station_org_id_idx').on(t.orgId),
    // Target of composite foreign keys, so a row can't point at a station of another org.
    unique('station_id_org_id_key').on(t.id, t.orgId),
  ],
);

export const user = pgTable(
  'user',
  {
    id: id(),
    /** Stored lowercase (the contract normalizes it). */
    email: text('email').notNull(),
    name: text('name').notNull(),
    createdAt: createdAt(),
    updatedAt: updatedAt(),
  },
  (t) => [uniqueIndex('user_email_key').on(sql`lower(${t.email})`)],
);

export const membership = pgTable(
  'membership',
  {
    id: id(),
    userId: uuid('user_id')
      .notNull()
      .references(() => user.id, { onDelete: 'cascade' }),
    orgId: uuid('org_id')
      .notNull()
      .references(() => organization.id, { onDelete: 'cascade' }),
    /** `null` for org-level roles. */
    stationId: uuid('station_id'),
    role: text('role').$type<Role>().notNull(),
    createdAt: createdAt(),
  },
  (t) => [
    foreignKey({
      name: 'membership_station_org_fk',
      columns: [t.stationId, t.orgId],
      foreignColumns: [station.id, station.orgId],
    }).onDelete('cascade'),
    unique('membership_user_org_station_key').on(t.userId, t.orgId, t.stationId).nullsNotDistinct(),
    index('membership_org_id_idx').on(t.orgId),
    index('membership_station_id_idx').on(t.stationId),
    check(
      'membership_role_level_check',
      sql`(${t.role} in ('owner', 'admin') and ${t.stationId} is null)
        or (${t.role} in ('station_manager', 'programmer', 'presenter', 'viewer') and ${t.stationId} is not null)`,
    ),
  ],
);

export const apiKey = pgTable(
  'api_key',
  {
    id: id(),
    orgId: uuid('org_id')
      .notNull()
      .references(() => organization.id, { onDelete: 'cascade' }),
    /** `null` when the key covers every station of the org. */
    stationId: uuid('station_id'),
    name: text('name').notNull(),
    /** Public first characters of the key (`ondes_ab12cd34`), to tell keys apart. */
    prefix: text('prefix').notNull(),
    /** SHA-256 of the full key, hex. The key itself is shown once and never stored. */
    keyHash: text('key_hash').notNull().unique(),
    scopes: text('scopes').array().notNull(),
    createdBy: uuid('created_by').references(() => user.id, { onDelete: 'set null' }),
    expiresAt: timestamp('expires_at', { withTimezone: true }),
    lastUsedAt: timestamp('last_used_at', { withTimezone: true }),
    revokedAt: timestamp('revoked_at', { withTimezone: true }),
    createdAt: createdAt(),
  },
  (t) => [
    foreignKey({
      name: 'api_key_station_org_fk',
      columns: [t.stationId, t.orgId],
      foreignColumns: [station.id, station.orgId],
    }).onDelete('cascade'),
    index('api_key_org_id_idx').on(t.orgId),
  ],
);

/**
 * Append-only record of every mutation made through the api. No foreign keys on purpose: the
 * history outlives the rows it describes.
 */
export const auditLog = pgTable(
  'audit_log',
  {
    id: id(),
    /** `null` for global entities (users). */
    orgId: uuid('org_id'),
    stationId: uuid('station_id'),
    actorType: text('actor_type').$type<ActorType>().notNull(),
    /** User or API key id; the job/script name for `system`. */
    actorId: text('actor_id'),
    action: text('action').notNull(),
    entityType: text('entity_type').notNull(),
    entityId: text('entity_id').notNull(),
    diff: jsonb('diff').$type<AuditDiff>().notNull().default({}),
    at: timestamp('at', { withTimezone: true }).notNull().defaultNow(),
  },
  (t) => [
    index('audit_log_org_id_at_idx').on(t.orgId, t.at),
    index('audit_log_station_id_at_idx').on(t.stationId, t.at),
    index('audit_log_entity_idx').on(t.entityType, t.entityId),
  ],
);
